import os, pathlib, subprocess, textwrap, json, sys
root=pathlib.Path('/workspace/repo-vul/src-vul')
print([p.name for p in root.iterdir()][:20])
for p in ['/workspace/repo-vul/src-vul/build','/workspace/repo-vul/src-vul/build-asan','/workspace/repo-vul/build']:
    pp=pathlib.Path(p); print(p, pp.exists(), list(pp.iterdir())[:5] if pp.exists() else '')
# find executables named exrcheck/fuzzer maybe built
matches=[]
for dirpath, dirs, files in os.walk('/workspace/repo-vul'):
    # prune .git maybe
    dirs[:] = [d for d in dirs if d not in ['.git'] and not d.startswith('_deps')]
    for f in files:
        if 'exrcheck' in f or 'fuzzer' in f:
            path=pathlib.Path(dirpath)/f
            try:
                st=path.stat()
                if st.st_mode & 0o111: matches.append(str(path))
            except: pass
print('\n'.join(matches[:50]), 'count', len(matches))
